import{c as n,Q as a,j as e,m as p}from"./chunks/framework.DOi4mjdC.js";const t="/assets/%E6%B5%81%E6%B0%B4%E7%BA%BF%E5%B9%B6%E8%A1%8C%E7%A4%BA%E6%84%8F%E5%9B%BE.CZD3rKaY.png",l="/assets/%E7%9F%A9%E9%98%B5%E7%BC%96%E7%A8%8B%E9%80%BB%E8%BE%91%E4%BD%8D%E7%BD%AE%E7%A4%BA%E6%84%8F%E5%9B%BE.BOL_WGdj.png",o="/assets/%E7%9F%A2%E9%87%8F%E7%BC%96%E7%A8%8BQueue%E9%98%9F%E5%88%97.DO6MHHjv.png",i="/assets/%E5%86%85%E5%AD%98%E7%AE%A1%E7%90%86%E7%A4%BA%E6%84%8F%E5%9B%BE.X1HITxd5.png",r="/assets/%E6%B5%81%E6%B0%B4%E4%BB%BB%E5%8A%A1%E7%A4%BA%E6%84%8F%E5%9B%BE.CCj3TNOu.png",c="/assets/%E6%B5%81%E6%B0%B4%E4%BB%BB%E5%8A%A1%E8%BF%90%E8%A1%8C%E7%A4%BA%E6%84%8F%E5%9B%BE.DKlrj_dc.png",u="/assets/%E7%9F%A9%E9%98%B5%E7%BC%96%E7%A8%8B%E9%80%BB%E8%BE%91%E4%BD%8D%E7%BD%AE%E7%A4%BA%E6%84%8F%E5%9B%BE-2.CW0IeDhk.png",m="/assets/%E7%9F%A9%E9%98%B5%E7%BC%96%E7%A8%8B%E9%80%BB%E8%BE%91%E4%BD%8D%E7%BD%AE%E7%A4%BA%E6%84%8F%E5%9B%BE-3.DTKr1M9P.png",B="/assets/%E7%9F%A9%E9%98%B5%E7%BC%96%E7%A8%8B%E9%80%BB%E8%BE%91%E4%BD%8D%E7%BD%AE%E7%A4%BA%E6%84%8F%E5%9B%BE-4.Bd11a7KC.png",g="/assets/%E8%9E%8D%E5%90%88%E7%AE%97%E5%AD%90%E7%BC%96%E7%A8%8B%E8%8C%83%E5%BC%8F.Cl8wr4fD.png",_=JSON.parse('{"title":"TPipe和TQue编程范式","description":"","frontmatter":{},"headers":[{"level":1,"title":"TPipe和TQue编程范式","slug":"tpipe和tque编程范式"},{"level":2,"title":"矢量编程范式","slug":"矢量编程范式"},{"level":2,"title":"矩阵编程范式","slug":"矩阵编程范式"},{"level":2,"title":"融合算子编程范式","slug":"融合算子编程范式"},{"level":2,"title":"小结","slug":"小结"}],"relativePath":"guide/编程指南/编程模型/AI-Core-SIMD编程/基于TPipe-TQue框架编程/TPipe-TQue框架编程范式.md","filePath":"guide/编程指南/编程模型/AI-Core-SIMD编程/基于TPipe-TQue框架编程/TPipe-TQue框架编程范式.md"}'),d={name:"guide/编程指南/编程模型/AI-Core-SIMD编程/基于TPipe-TQue框架编程/TPipe-TQue框架编程范式.md"};function C(E,s,T,b,f,A){return a(),e("div",null,[...s[0]||(s[0]=[p('<h1 id="tpipe和tque编程范式" tabindex="-1">TPipe和TQue编程范式 <a class="header-anchor" href="#tpipe和tque编程范式" aria-label="Permalink to &quot;TPipe和TQue编程范式&quot;">​</a></h1><p>上一章阐述了TPipe‑TQue编程模型的底层设计原理：基于经典C/C++队列管道（Queue Pipeline）思想，将算子任务拆分为多级流水Stage，依靠TQue队列解决写后读数据依赖、依靠AllocTensor/FreeTensor解决读后写内存复用冲突，通过底层同步指令实现多单元异步并行的时序安全。</p><p>本章将上述原理固化为可直接编码的标准化编程范式。上一章回答<strong>为什么这样设计</strong>，本章则聚焦<strong>如何按此设计编写代码</strong>。TPipe‑TQue编程范式的本质，是队列管道思想在AI Core上的工程化落地——它将流水线拆分、队列同步、内存生命周期管理、异步并行调度等复杂底层逻辑，封装为一套统一、固定的开发流程，帮助开发者快速编写规范、可流水且高性能的算子核函数。</p><p>该范式定义了算子核函数实现的标准化固定流程。开发者严格遵循此范式，无需手动编写底层同步逻辑，也不必独自处理数据依赖与时序阻塞，即可快速搭建稳定、高效的算子代码框架。</p><p>从硬件执行形态看，AI Core内部的向量单元、矩阵单元和数据搬运单元天然支持异步并行与流水线执行。TPipe‑TQue编程范式完全贴合这一硬件特性，将硬件的多级流水行为抽象为软件层面统一的<strong>数据搬入—计算—数据搬出</strong>三段式流水线开发模型。</p><p>流水并行的核心逻辑可通过示意图直观理解：完整算子任务被拆分为多个有序子阶段，不同硬件单元负责不同工序；同一数据分片需在各阶段间串行流动，以保证数据依赖合法；不同数据分片则可在不同阶段同时处理，实现流水线吞吐叠加，与经典C/C++管道程序的执行逻辑完全一致。</p><p><strong>图 1</strong> 流水线并行示意图<br><img src="'+t+'" alt="" title="流水线并行示意图"></p><p>结合上一章的阐述可总结出：Ascend C流水线体系由两大核心模块共同支撑：</p><ul><li><strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/TPipe.md" target="_blank" rel="noreferrer">TPipe</a></strong> 资源管理器：统一管理系统内存资源和用于同步的事件等；</li><li><strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/TQue.md" target="_blank" rel="noreferrer">TQue</a></strong> 队列：完成Stage任务之间的同步和通信。</li></ul><p>基于这套机制，Ascend C固化了矢量、矩阵、融合三类算子的标准化流水线编程范式。下文将结合硬件特性与工程实例逐一展开。</p><ul><li><strong><a href="./TPipe-TQue编程范式.html#section116515238815">矢量编程范式</a></strong></li><li><strong><a href="./TPipe-TQue编程范式.html#section8213173433312">矩阵编程范式</a></strong></li><li><strong><a href="./TPipe-TQue编程范式.html#section57815481855">融合算子编程范式</a></strong></li></ul><h2 id="矢量编程范式" tabindex="-1">矢量编程范式 <a class="header-anchor" href="#矢量编程范式" aria-label="Permalink to &quot;矢量编程范式&quot;">​</a></h2><p><img src="'+l+'" alt=""></p><p>如上图所示，矢量编程范式将算子实现流程划分为三个基本任务：CopyIn、Compute和CopyOut。</p><ul><li><strong>CopyIn</strong>负责数据搬入：将输入数据从Global Memory搬运到Local Memory（VECIN表示矢量计算搬入数据的存放位置），搬运完成后将数据入队；</li><li><strong>Compute</strong>负责矢量指令计算：从队列取出数据后，在Local Memory上执行计算，计算完成后将结果入队；</li><li><strong>CopyOut</strong>负责数据搬出：从队列取出计算结果，将其从Local Memory（VECOUT表示矢量计算搬出数据的存放位置）搬运回Global Memory。</li></ul><p>上述VECIN、VECOUT均属于TPosition（逻辑位置）概念。Ascend C通过抽象的TPosition表达不同层级的物理存储，以替代直接的片上物理存储概念，实现硬件架构的隐藏。除VECIN和VECOUT外，矢量编程中还会用到VECCALC，通常在定义临时变量时使用。</p><p>从编程角度看，具体流程（如下方伪代码所示）及流程图如下：</p><p><img src="'+o+`" alt=""></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::TPipe pipe;                                // 创建全局资源管理器</span></span>
<span class="line"><span>AscendC::TQue&lt;AscendC::TPosition::VecIn, 1&gt; queIn;  // 创建CopyIn阶段队列</span></span>
<span class="line"><span>AscendC::TQue&lt;AscendC::TPosition::VecOut, 1&gt; queOut;// 创建CopyOut阶段队列</span></span>
<span class="line"><span>// Init 阶段</span></span>
<span class="line"><span>pipe.InitBuffer(queIn, 2, 1024);                    // 开启DoubleBuffer，将待处理数据一分为二，实现流水并行</span></span>
<span class="line"><span>pipe.InitBuffer(queOut, 2, 1024);</span></span>
<span class="line"><span>for-loop {</span></span>
<span class="line"><span>    // CopyIn 阶段</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        auto tensor = queIn.AllocTensor&lt;half&gt;();   // 从队列申请资源，长度1024</span></span>
<span class="line"><span>        AscendC::DataCopy(tensor, gm, 1024);       // 将数据从GM搬运至VECIN</span></span>
<span class="line"><span>        queIn.EnQue(tensor);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    // Compute 阶段</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        auto tensor = queIn.DeQue&lt;half&gt;();</span></span>
<span class="line"><span>        auto tensorOut = queOut.AllocTensor&lt;half&gt;();</span></span>
<span class="line"><span>        AscendC::Abs(tensorOut, tensor, 1024);    // 执行计算</span></span>
<span class="line"><span>        queIn.FreeTensor(tensor);</span></span>
<span class="line"><span>        queOut.EnQue(tensorOut);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    // CopyOut 阶段</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        auto tensor = queOut.DeQue&lt;half&gt;();</span></span>
<span class="line"><span>        AscendC::DataCopy(gmOut, tensor, 1024);   // 将数据从VECOUT搬运至GM</span></span>
<span class="line"><span>        queOut.FreeTensor(tensor);                // 释放资源</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>任务间数据传递所使用的内存、事件等资源，统一由TPipe管理。如下内存管理示意图所示，TPipe通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/InitBuffer.md" target="_blank" rel="noreferrer">InitBuffer</a>接口对外提供队列内存初始化功能，开发者可通过该接口为指定队列分配内存。</p><p>队列内存初始化完成后，当需要内存时通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/AllocTensor.md" target="_blank" rel="noreferrer">AllocTensor</a>为LocalTensor分配内存；当该LocalTensor完成相关计算不再使用时，再调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/FreeTensor.md" target="_blank" rel="noreferrer">FreeTensor</a>回收其内存。</p><p><strong>图 2</strong> 内存管理示意图<br><img src="`+i+'" alt="" title="内存管理示意图"></p><p>编程过程中使用的临时变量内存同样由TPipe管理。临时变量可使用TBuf数据结构申请指定TPosition上的存储空间。通过TBuf申请的内存仅能参与计算，不可执行队列的入队、出队操作。具体接口使用说明请参见<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/TBuf.md" target="_blank" rel="noreferrer">TBuf</a>。</p><p>遵循上述范式编程，即可实现单核数据的并行处理。待处理数据被切分为多个分片，每个并行任务依次完成对所有分片的处理。任务间的箭头表示数据依赖，例如CopyIn完成第一个分片的处理后，Compute才能开始处理该分片。</p><p><strong>图 3</strong> 流水任务示意图<br><img src="'+r+'" alt="" title="流水任务示意图"></p><p>上图对应的流水任务运行时序如下图所示。可以看出：对于同一数据分片，CopyIn、Compute、CopyOut之间存在依赖，必须串行执行；对于不同数据分片，同一时刻可有多个任务并行处理，从而以任务级并行提升整体性能。</p><p><strong>图 4</strong> 流水任务运行示意图<br><img src="'+c+'" alt="" title="流水任务运行示意图"></p><h2 id="矩阵编程范式" tabindex="-1">矩阵编程范式 <a class="header-anchor" href="#矩阵编程范式" aria-label="Permalink to &quot;矩阵编程范式&quot;">​</a></h2><p>Cube计算的典型数据流图如下所示：</p><p><img src="'+u+'" alt=""></p><p>与矢量编程一致，矩阵编程同样使用逻辑位置（TPosition）表达数据流，主要使用的TPosition定义如下：</p><ul><li>A1：用于存放左矩阵的逻辑内存，物理对应AI Core的L1 Buffer。</li><li>B1：用于存放右矩阵的逻辑内存，物理对应AI Core的L1 Buffer。</li><li>C1：用于存放Bias（偏置）数据的逻辑内存，物理对应AI Core的L1 Buffer或Unified Buffer。</li><li>A2：用于存放小块左矩阵（经分割适配L0A Buffer容量）的逻辑内存，物理对应AI Core的L0A Buffer。</li><li>B2：用于存放小块右矩阵（经分割适配L0B Buffer容量）的逻辑内存，物理对应AI Core的L0B Buffer。</li><li>C2：用于存放小块Bias数据（经分割适配BT Buffer容量）的逻辑内存，物理对应AI Core的BT Buffer或L0C Buffer。</li><li>CO1：用于存放小块矩阵计算结果（如切分后的结果分块）的逻辑内存，物理对应AI Core的L0C Buffer。</li><li>CO2：用于存放最终矩阵计算结果的逻辑内存，物理对应Global Memory或AI Core的Unified Buffer。</li><li>VECIN：用于存放矢量计算输入数据的逻辑内存，物理对应AI Core的Unified Buffer。</li><li>VECCALC：用于存放矢量计算临时变量的逻辑内存，物理对应AI Core的Unified Buffer。</li><li>VECOUT：用于存放矢量计算输出数据的逻辑内存，物理对应AI Core的Unified Buffer。</li></ul><p>Cube计算流程本质上也可归纳为CopyIn、Compute、CopyOut三个阶段。因其流程相对复杂，Matmul高阶API提供了高阶封装，有效简化了编程范式。</p><p><img src="'+m+`" alt=""></p><p>如图所示：CopyIn阶段对应<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetTensorA.md" target="_blank" rel="noreferrer">SetTensorA</a>、<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetTensorB.md" target="_blank" rel="noreferrer">SetTensorB</a>、<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetBias.md" target="_blank" rel="noreferrer">SetBias</a>接口；Compute阶段对应<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Iterate.md" target="_blank" rel="noreferrer">Iterate</a>接口；CopyOut阶段对应<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/GetTensorC.md" target="_blank" rel="noreferrer">GetTensorC</a>接口。示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 创建Matmul对象，需传入A、B、C、Bias的参数类型信息</span></span>
<span class="line"><span>// 类型信息通过MatmulType定义，包括：内存逻辑位置、数据格式、数据类型</span></span>
<span class="line"><span>typedef MatmulType&lt;TPosition::GM, CubeFormat::ND, half&gt; aType;</span></span>
<span class="line"><span>typedef MatmulType&lt;TPosition::GM, CubeFormat::ND, half&gt; bType;</span></span>
<span class="line"><span>typedef MatmulType&lt;TPosition::GM, CubeFormat::ND, float&gt; cType;</span></span>
<span class="line"><span>typedef MatmulType&lt;TPosition::GM, CubeFormat::ND, float&gt; biasType;</span></span>
<span class="line"><span>Matmul&lt;aType, bType, cType, biasType&gt; mm;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling); // 初始化</span></span>
<span class="line"><span>// CopyIn阶段：完成从GM到Local Memory的搬运</span></span>
<span class="line"><span>mm.SetTensorA(gm_a);    // 设置左矩阵A</span></span>
<span class="line"><span>mm.SetTensorB(gm_b);    // 设置右矩阵B</span></span>
<span class="line"><span>mm.SetBias(gm_bias);    // 设置Bias</span></span>
<span class="line"><span>// Compute阶段：执行矩阵乘计算</span></span>
<span class="line"><span>while (mm.Iterate()) {</span></span>
<span class="line"><span>    // CopyOut阶段：完成从Local Memory到GM的搬运</span></span>
<span class="line"><span>    mm.GetTensorC(gm_c);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 结束矩阵乘操作</span></span>
<span class="line"><span>mm.End();</span></span></code></pre></div><h2 id="融合算子编程范式" tabindex="-1">融合算子编程范式 <a class="header-anchor" href="#融合算子编程范式" aria-label="Permalink to &quot;融合算子编程范式&quot;">​</a></h2><p>支持Vector与Cube混合计算的算子称为融合算子。Ascend C提供<strong>融合算子的编程范式</strong>，方便开发者基于该范式表达融合算子的数据流，快速实现自定义融合算子。</p><p><strong>融合算子数据流</strong>指其输入输出在各存储位置间的流向。以一个典型的Cube与Vector融合算子为例，逻辑位置间的数据流向如下图所示（为简化描述，未列出Bias）：</p><ul><li>Cube的输出可作为Vector的输入：CO2→VECIN</li><li>Vector的输出也可作为Cube的输入：VECOUT→A1→A2、VECOUT→B1→B2</li></ul><p><img src="`+B+'" alt=""></p><p>基于Matmul高阶API的融合算子编程范式，将上述数据流简化为以下步骤：</p><p><strong>图 5</strong> 融合算子编程范式<br><img src="'+g+`" alt="" title="融合算子编程范式"></p><ol><li>初始化MatMul对象，将输入数据从Global Memory搬运到Cube核上。</li><li>执行MatMul内部计算。</li><li>将MatMul计算结果搬运到Vector核上。</li><li>执行Vector矢量计算。</li><li>将输出结果搬运回Global Memory。</li></ol><p>示例代码如下（伪代码）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename aType, typename bType, typename cType, typename biasType&gt;</span></span>
<span class="line"><span>__aicore__ inline void MatmulLeakyKernel&lt;aType, bType, cType, biasType&gt;::Process()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // 步骤1：初始化MatMul对象，将输入数据从Global Memory搬运到Cube核上</span></span>
<span class="line"><span>    uint32_t computeRound = 0;</span></span>
<span class="line"><span>    REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), matmulObj);</span></span>
<span class="line"><span>    matmulObj.Init(&amp;tiling);</span></span>
<span class="line"><span>    matmulObj.SetTensorA(aGlobal);</span></span>
<span class="line"><span>    matmulObj.SetTensorB(bGlobal);</span></span>
<span class="line"><span>    matmulObj.SetBias(biasGlobal);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    while (matmulObj.template Iterate&lt;true&gt;()) { // 步骤2：执行MatMul内部计算</span></span>
<span class="line"><span>        // 步骤3：将MatMul计算结果搬运到Vector核上</span></span>
<span class="line"><span>        reluOutLocal = reluOutQueue_.AllocTensor&lt;cType&gt;();</span></span>
<span class="line"><span>        matmulObj.template GetTensorC&lt;true&gt;(reluOutLocal, false, true);</span></span>
<span class="line"><span>        // 步骤4：执行Vector矢量计算</span></span>
<span class="line"><span>        AscendC::LeakyRelu(reluOutLocal, reluOutLocal, (cType)alpha, tiling.baseM * tiling.baseN);</span></span>
<span class="line"><span>        reluOutQueue_.EnQue(reluOutLocal);</span></span>
<span class="line"><span>        // 步骤5：将输出结果搬运回Global Memory</span></span>
<span class="line"><span>        reluOutQueue_.DeQue&lt;cType&gt;();</span></span>
<span class="line"><span>        ...</span></span>
<span class="line"><span>        AscendC::DataCopy(cGlobal[startOffset], reluOutLocal, copyParam);</span></span>
<span class="line"><span>        reluOutQueue_.FreeTensor(reluOutLocal);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        computeRound++;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    matmulObj.End();</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>本章内容完全承接上一章的队列管道底层原理，将理论中的Stage流水线拆分、数据依赖与同步等，落地为Ascend C统一的工程编程范式。无论是简单矢量算子、高密度矩阵算子，还是复杂融合算子，其本质都是经典C/C++队列管道模型在AI Core异构硬件上的不同形态实现：通过标准化三段式流水、队列数据同步、统一资源管控，屏蔽底层复杂的并行时序与内存冲突问题，让开发者以统一、简洁、可复用的流水线思维，高效开发高性能算子。</p>`,48)])])}const y=n(d,[["render",C]]);export{_ as __pageData,y as default};
